parameters.jsCode:
const ai = $json.output[0].content[0].text;

return {
  json: {
    Intent: ai.intent,
    Summary: ai.summary,
    Confidence: ai.confidence,
    RecommendedAction: ai.recommendedAction,
    Sentiment: ai.sentiment,
    Priority: ai.priority,
    MeetingRequested: ai.meetingRequested,
    CallbackRequested: ai.callbackRequested,
    CallbackDate: ai.callbackDate,
    CallbackTime: ai.callbackTime
  }
};

